con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tabs = [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
files = sorted(glob.glob('scripts/migrations/data_*.sql'))
print(len(files), "data migration files")

# Convention A: executable DML reference — INSERT INTO / UPDATE / DELETE FROM / SELECT ... FROM/JOIN <table>
# after stripping -- comments and /* */ blocks.
# Convention B: any mention of the bare token anywhere in the file (incl. comments).
dml_pat = {}
any_pat = {}
def strip_comments(sql):
    sql = re.sub(r'/\*.*?\*/', '', sql, flags=re.S)
    return "\n".join(l.split('--')[0] for l in sql.splitlines())

dml = {t: set() for t in tabs}
mention = {t: set() for t in tabs}
for f in files:
    raw = open(f).read()
    code = strip_comments(raw)
    for t in tabs:
        if re.search(r'\b%s\b' % re.escape(t), raw):
            mention[t].add(f)
        if re.search(r'\b(?:INSERT\s+INTO|UPDATE|DELETE\s+FROM|FROM|JOIN)\s+"?%s"?\b' % re.escape(t), code, re.I):
            dml[t].add(f)

print(f"{'table':38} {'DML files':>9} {'mention files':>13}")
for t in sorted(tabs, key=lambda t:-len(dml[t])):
